insert into product_archive_shoe_size_chart_row (chart_id, size_value, china_size, us_size, foot_length_mm, foot_range_cm, inner_length_mm, age_segment, reference_age, reference_stage, general_mapping_text, douyin_mapping_text, vip_mapping_text, video_pdd_vip_mapping_text, pinduoduo_mapping_text, enabled, updated_at)
select chart.id, src.size_value, src.china_size, src.us_size, src.foot_length_mm, src.foot_range_cm, src.inner_length_mm, src.age_segment, src.reference_age, src.reference_stage, src.general_mapping_text, src.douyin_mapping_text, src.vip_mapping_text, src.video_pdd_vip_mapping_text, src.pinduoduo_mapping_text, true, now() from source_rows src join product_archive_shoe_size_chart chart on chart.chart_code = src.chart_code
on conflict (chart_id, size_value) do update set
  china_size = excluded.china_size,
  us_size = excluded.us_size,
  foot_length_mm = excluded.foot_length_mm,
  foot_range_cm = excluded.foot_range_cm,
  inner_length_mm = excluded.inner_length_mm,
  age_segment = excluded.age_segment,
  reference_age = excluded.reference_age,
  reference_stage = excluded.reference_stage,
  general_mapping_text = excluded.general_mapping_text,
  douyin_mapping_text = excluded.douyin_mapping_text,
  vip_mapping_text = excluded.vip_mapping_text,
  video_pdd_vip_mapping_text = excluded.video_pdd_vip_mapping_text,
  pinduoduo_mapping_text = excluded.pinduoduo_mapping_text,
  enabled = true, updated_at = now();

update product_archive_shoe_size_chart set enabled = false, updated_at = now()
where chart_code in ('open_sandal', 'closed_sandal');
update product_archive_shoe_size_chart_row set enabled = false, updated_at = now()
where chart_id in (select id from product_archive_shoe_size_chart where chart_code in ('open_sandal', 'closed_sandal'));
-- 41/42 have no measurements in either new block. Never retain old active values.
update product_archive_shoe_size_chart_row set enabled = false, updated_at = now()
where chart_id in (select id from product_archive_shoe_size_chart where chart_code in ('sport_leisure', 'sandal')) and size_value not between 15 and 40;
update product_archive_shoe_size_chart set version_label = '2026-09', source_file_name = '巴拉巴拉鞋品尺码表2026新(1).xlsx', updated_at = now()
where chart_code in ('sport_leisure', 'sandal');
update product_archive_shoe_size_chart set chart_name = '运动鞋/休闲鞋/婴童鞋/其他', applicable_categories = '运动鞋/休闲鞋/婴童鞋/其他'
where chart_code = 'sport_leisure';
